package dev.kuan.kuanperion.automation;
import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.*;
public final class BookServiceTest {
 static final long S=1_000_000_000L;
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
 static final class H {
  final BookCombineTaskTest.Fake f=new BookCombineTaskTest.Fake();final InventoryReceipts items=new InventoryReceipts();final CursorReceipts cursors=new CursorReceipts();final AtomicBoolean closed=new AtomicBoolean(true);final int[] hooks={0,0},factories={0};
  final AutomationSession session=new AutomationSession(new AutomationCoordinator(),f::context,()->hooks[0]++,()->hooks[1]++);final List<StashService.Notice> notices=new ArrayList<>();final BookService service;
  H(AutomationSettingsStore store){f.cursor=cursors;service=new BookService(store,session,items,cursors,f::context,p->{factories[0]++;return f;},BookCombineTaskTest.LAYOUT,closed::get,notices::add);}
 }
 public static void main(String[]args)throws Exception{
  var dir=Files.createTempDirectory("book-service-");try{
   var path=dir.resolve("automation.json");var store=AutomationSettingsStore.load(path);check(store.bookPolicyValid()&&store.bookPolicy().ceilings().isEmpty()&&!store.enabled(AutomationFeature.BOOK_COMBINE),"empty consent/off defaults");
   var h=new H(store);h.service.tick(0);check(h.factories[0]==0&&!h.service.manualRequest(0),"no empty-authorization factory/data/commands");
   var policy=BookCombineTaskTest.policy();store.setBookPolicy(policy);store.setEnabled(AutomationFeature.BOOK_COMBINE,true);check(AutomationSettingsStore.load(path).bookPolicy().equals(policy),"book settings outside jar, restart-safe");
   h.closed.set(false);check(h.service.manualRequest(0)&&h.service.pending(),"bounded explicit UI request");h.service.tick(S);check(h.f.opens==0&&h.factories[0]==0,"no native controller until settings screen closes");h.closed.set(true);h.service.tick(2*S);check(h.service.active()&&h.f.opens==1&&h.hooks[0]==1,"exact one pair and original Farm hold on close");
   h.service.suspend(3*S);check(!h.service.active()&&!h.service.autoEnabled()&&h.hooks[1]==1&&h.f.returns==0&&h.f.closed==0,"manual/Jerry stop never repair or close an uncertain menu");
   byte[] prefs=Files.readAllBytes(path);h.service.tick(100*S);check(h.f.opens==1&&Arrays.equals(prefs,Files.readAllBytes(path)),"idle suspend no replay/no rewrite");
   store.setEnabled(AutomationFeature.BOOK_COMBINE,true);h=new H(store);h.closed.set(false);check(h.service.manualRequest(0),"expiry setup");h.service.tick(31*S);h.closed.set(true);h.service.tick(32*S);check(!h.service.pending()&&h.f.opens==1,"stale manual intent expires; separately enabled automatic job may dispatch once");h.service.cancel(33*S);
   h=new H(store);h.closed.set(false);check(h.service.manualRequest(0),"world-bound UI intent");h.f.ctx=new AutomationContext(2,true,true,Set.of());h.service.tick(S);check(!h.service.pending()&&h.factories[0]==0,"world change invalidates intent without creating native driver");
   store.setEnabled(AutomationFeature.BOOK_COMBINE,true);h=new H(store);var occupied=h.session.begin(AutomationFeature.PEST,0,60*S);check(occupied!=null,"busy setup");h.service.tick(S);check(h.factories[0]==0,"another root prevents even native inventory preflight");h.session.finish(occupied,true,S);h.service.tick(S);check(h.f.opens==1,"busy poll never consumes due throttle");h.service.cancel(2*S);
   store.setEnabled(AutomationFeature.BOOK_COMBINE,true);h=new H(store);h.service.tick(0);h.service.tick(S);check(h.f.transfers==1,"input started before cancellation test");h.f.input(9,20,h.items);h.service.tick(2*S);h.service.cancel(3*S);h.service.tick(4*S);check(!h.service.active()&&h.f.returns==0&&h.f.closed==0&&h.f.transfers==1,"explicit user stop does not schedule recovery effects");
   store.setEnabled(AutomationFeature.BOOK_COMBINE,true);h=new H(store);h.service.tick(0);h.f.outcome=GuardedMenuAction.Result.UNCERTAIN;h.service.tick(S);check(!h.service.active()&&!h.service.autoEnabled()&&!store.enabled(AutomationFeature.BOOK_COMBINE)&&h.notices.size()==1&&h.notices.getFirst().warning(),"uncertain action disables automatic retry and reports manual recovery");h.service.tick(100*S);check(h.f.transfers==1,"no next-pair retry after uncertainty");
   store.setEnabled(AutomationFeature.BOOK_COMBINE,true);h=new H(store);h.service.tick(0);h.closed.set(false);h.service.tick(S);check(h.service.active()&&h.f.transfers==1,"expected Anvil opening is not cancelled before its first receipt-guarded bind");h.f.input(9,20,h.items);h.service.tick(2*S);h.service.tick(3*S);h.f.input(10,24,h.items);h.f.placed.put(13,BookCombineTaskTest.book(-1,5,"preview",1));h.items.observe(1,4,13,h.f.placed.get(13).item());h.items.observe(1,4,22,h.f.menu().item(22));h.service.tick(4*S);h.service.tick(5*S);
   h.f.placed.clear();h.f.placed.put(22,BookCombineTaskTest.book(-1,5,"result",1));h.items.observe(1,4,20,BookCombineTaskTest.empty());h.items.observe(1,4,24,BookCombineTaskTest.empty());h.items.observe(1,4,22,h.f.placed.get(22).item());h.cursors.observe(1,4,BookCombineTaskTest.empty(),6*S);h.service.tick(6*S);h.service.tick(7*S);
   h.f.placed.clear();h.f.inventory.put(9,BookCombineTaskTest.book(9,5,"result",1));h.items.observe(1,4,22,h.f.menu().item(22));h.items.observe(1,0,9,h.f.inventory.get(9).item());h.cursors.observe(1,4,BookCombineTaskTest.empty(),8*S);h.service.tick(8*S);check(!h.service.active()&&h.service.autoEnabled()&&h.f.closed==1&&h.hooks[1]==0&&h.notices.size()==1&&!h.notices.getFirst().warning(),"server-proven one-pair completion closes owned menu and releases original Farm");h.service.tick(9*S);check(h.f.opens==1,"success cooldown prevents immediate next pair");
   var conflictPath=dir.resolve("conflict.json");var conflict=AutomationSettingsStore.load(conflictPath);conflict.setBookPolicy(policy);conflict.setEnabled(AutomationFeature.BOOK_COMBINE,true);var conflictH=new H(conflict);Files.writeString(conflictPath,Files.readString(conflictPath)+" ");try{conflictH.service.setEnabled(false);throw new AssertionError("expected conflicting write");}catch(java.io.IOException expected){}check(!conflictH.service.autoEnabled(),"failed disable write still suppresses this session");
   var farmPath=dir.resolve("farm.json");var farmStore=AutomationSettingsStore.load(farmPath);farmStore.setBookPolicy(policy);farmStore.setEnabled(AutomationFeature.BOOK_COMBINE,true);var stopped=new H(farmStore);stopped.f.ctx=new AutomationContext(1,false,true,Set.of());stopped.service.tick(0);check(stopped.factories[0]==0,"only-while-Farming guard precedes native preflight");stopped.closed.set(false);check(stopped.service.manualRequest(0),"deliberate manual work does not require Farming");stopped.f.ctx=new AutomationContext(1,true,true,Set.of());stopped.service.tick(S);check(!stopped.service.pending()&&stopped.factories[0]==0,"changed Farm generation/state cancels queued intent");
   for(String bad:List.of("{\"ceilings\":{\"harvesting\":\"5\"}}","{\"ceilings\":{\"harvesting\":5.5}}","{\"ceilings\":{\"harvesting\":11}}","{\"ceilings\":[]}","{\"protectedUuids\":[\"a\",\"a\"]}","{\"delayMillis\":100}","{\"onlyWhileFarming\":1}")){
    Files.writeString(path,"{\"schemaVersion\":1,\"features\":{\"bookCombine\":true},\"bookCombine\":"+bad+"}");var invalid=AutomationSettingsStore.load(path);check(!invalid.bookPolicyValid()&&invalid.bookPolicy().ceilings().isEmpty(),"malformed authority denied: "+bad);
   }
   Files.writeString(path,"{\"schemaVersion\":1,\"future\":7,\"bookCombine\":{\"future\":true}}");var preserve=AutomationSettingsStore.load(path);preserve.setBookPolicy(policy);check(Files.readString(path).contains("\"future\": 7")&&Files.readString(path).contains("\"future\": true"),"unknown root/section data preserved");
   Files.writeString(path,"{\"schemaVersion\":9}");check(!AutomationSettingsStore.load(path).bookPolicyValid(),"future schema cannot enable book task");
   System.out.println("BookServiceTest: PASS (strict persisted authorization, off defaults, bounded world-bound UI queue, busy root deferral, original Farm hold, no repair/replay on manual/Jerry/uncertainty)");
  }finally{try(var walk=Files.walk(dir)){for(var p:walk.sorted(Comparator.reverseOrder()).toList())Files.delete(p);}}
 }
}
